class Solution {
    public int daysBetweenDates(String date1, String date2) {
        return Math.abs(daysSince1971(date1) - daysSince1971(date2));
    }

    private int daysSince1971(String date) {
        int year = Integer.parseInt(date.substring(0, 4));
        int month = Integer.parseInt(date.substring(5, 7));
        int day = Integer.parseInt(date.substring(8, 10));

        int days = 0;
        // add full years from 1971 to year-1
        for (int y = 1971; y < year; y++) {
            days += isLeap(y) ? 366 : 365;
        }
        // days in months before current month in current year
        int[] md = {31,28,31,30,31,30,31,31,30,31,30,31};
        for (int m = 1; m < month; m++) {
            days += md[m-1];
            if (m == 2 && isLeap(year)) days += 1; // February in leap year
        }
        // add days in current month (day-1 to make 1971-01-01 -> 0)
        days += day - 1;
        return days;
    }

    private boolean isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }
}

